// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(uint256 dummy) public {

        bool ok;
        try c.version() returns (string memory v) {
            bytes memory rb = bytes(v);
            bytes memory expect = bytes("1.0.0");
            if (rb.length == expect.length) {
                bool eq = true;
                for (uint i = 0; i < rb.length; i++) {
                    if (rb[i] != expect[i]) { eq = false; break; }
                }
                ok = eq;
            } else {
                ok = false;
            }
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
